14	/**
15	 * Rejects a create request that is missing or blank in any required owner field, so an
16	 * incomplete body is a 400 whose {@code errors} array names each offending field. Also
17	 * normalizes the telephone to E.164 form (see {@link TelephoneE164}), republishing the
18	 * normalized value so it is stored and returned as {@code telephone}; a telephone that
19	 * cannot form a valid E.164 number is a 400 too.
20	 * The optional {@code email} is validated only when present: a syntactically invalid
21	 * address is a 400, otherwise it is normalized to lower-case and republished so it is
22	 * stored and returned lower-cased.
23	 * The {@code address} is normalized (see {@link AddressNormalizer}) and republished so it
24	 * is stored and returned in canonical form; an address that is blank after normalization
25	 * is a required-field 400.
26	 * Runs first and republishes the body as a variable for {@link BuildOwner}.
27	 */
28	public class ValidateOwnerFields {
29	
30	    /** Syntactic email check: one '@', non-empty local part, and a dotted domain. */
31	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
